local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a103213413e3b0c4"] = { "Temo che stia arrivando qualcosa di oscuro.", "." },
  ["a1065ac42f4f0683"] = { "Voglio unirmi a un gruppo diretto in questa spedizione. <Questa scelta ti metterà in coda alla pietra dell'incontro>", "." },
  ["a109d7b9158efdb9"] = { "Libertà! Finalmente le mie catene sono spezzate!", "." },
  ["a10a988922243366"] = { "Eva, ho perso la Spectral Essence. Me ne serve un'altra.", "." },
  ["a111acf490e5e8b4"] = { "Allenati duramente, allenati ogni giorno. E quando avrai perfezionato le tue abilità, torna da me.", "." },
  ["a118f0ffcf767521"] = { "Thrall ha mostrato grande bontà concedendomi asilo nel suo dominio. In ogni caso, non voglio abusare della sua ospitalità. Sarebbe un grande disonore portare guai al nostro capo.", "." },
  ["a11b47ad7b8317da"] = { "Salute, {class}. Sei qui per apprendere le arti occulte?", "." },
  ["a11e30da2ad5ceef"] = { "Sissignora!", "." },
  ["a11f1e664ffe31ff"] = { "Ladri! Fonderò i vostri resti!", "." },
  ["a125592f03f21950"] = { "%s sente la richiesta d'aiuto e si prepara alla battaglia!", "." },
  ["a1256152ce6abf79"] = { "Ehehe, mollaccione.", "." },
  ["a1282f42058ee168"] = { "Fuggi, prima che sia troppo tardi!", "." },
  ["a13e852ac72be8d7"] = { "Un branco di teppisti e di ladri non mi farà lasciare la mia terra!", "." },
  ["a13ed8f9afcae99e"] = { "Ancora qualcuno e le nostre stalle traboccheranno di cavalcature. Affidalo alla mia custodia, soldato. Da qui ci penso io.", "." },
  ["a13fe189c6103794"] = { "Arriva subito!", "." },
  ["a1460c13d6cfae15"] = { "Nelle nostre creazioni usiamo molte pelli e pellicce di animali.", "." },
  ["a148243d63315564"] = { "Sciocchi, sapevo che facendo leva sui deboli sentimenti di mio fratello avrebbe mandato dei «soccorritori».", "." },
  ["a14876e197d2acdb"] = { "Il ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧ non ti riconosce, {class}.", "." },
  ["a149a49c18e7e4cd"] = { "Avanti, miei servitori! Avanti! Che nessuno ci sbarri la strada!", "." },
  ["a14adfbe24801dd2"] = { "Lard mantiene pace qui. Lard vende anche pesce. Vuoi pesce?", "." },
  ["a14fa1c5971cb08e"] = { "Antichi, guidate la mia mano... Destatevi dal vostro sonno! DESTATEVI E SIGILLATE QUESTO LUOGO MALEDETTO!", "." },
  ["a1524cc099591162"] = { "Piccoli mortali, io QUI! Voi incontra destino!", "." },
  ["a156131a92382547"] = { "Vedi questo? È il mio bastone del bum! Il meglio dei nani. Proprio così, questo gioiellino è stato fatto a ⟦Ironforge=Forgiardente⟧, Khaz Modan. Costa circa centonove monete d'oro e novantacinque di rame. Ha il calcio in noce, acciaio di torio e un grilletto sensibilissimo.", "." },
  ["a15759d026b8da8f"] = { "Non troverai un tesoro di sapere più grande della Biblioteca Reale di ⟦Stormwind=Roccavento⟧!", "." },
  ["a15ef5a6ca1f8fab"] = { "L'ORGOGLIO ANNUNCIA LA FINE DEL TUO MONDO. VENITE, MORTALI! AFFRONTATE L'IRA DELLO SCORTICA ANIME!", "." },
  ["a1632fb1d12765d2"] = { "Alcuni non sopportano il calore della ⟦Great Forge=Grande Forgia⟧, ma per me è proprio quello giusto. Ed è il posto migliore per lavorare sul serio alla forgia.", "." },
  ["a1644a019652b25e"] = { "Inginocchiati davanti a me, verme!", "." },
  ["a167482546012318"] = { "Che razza di feccia osa entrare nelle mie stanze!?", "." },
  ["a16e47fbf8d1b98d"] = { "Amichevole.", "." },
  ["a16e9f11dc173209"] = { "Sì! Ce l'hanno fatta! I draghi fatati catturati ce l'hanno fatta!", "." },
  ["a16efba1026b2e64"] = { "Se non ne hai mai visto uno, è uno spettacolo da ammirare. Una creatura davvero impressionante sia dentro che fuori dal campo di battaglia. Ora passiamo a ciò che di sicuro voi studenti maschi stavate aspettando. La succube.", "." },
  ["a172666fb81027f1"] = { "Accidenti, non c'è bisogno di implorare! Comunque, ho quasi finito la storia.\n\nDunque, tutta la compagnia è in mezzo a quella sala enorme a contendersi questo amuleto, e sai come rimbomba là dentro! Alla fine si è rotto in tre pezzi, e abbiamo tirato i dadi, e i pezzi sono andati a varie persone o gruppi.\n\nIl resto è un po' confuso, però, perché è stato più o meno in quel momento che lo spirito del vecchio Valthalak ha deciso di fare la sua entrata e di evocare tutti quegli assassini spettrali.", "." },
  ["a177c14c3b313a8e"] = { "Non c'è niente come entrare in comunione con la natura... o almeno è quello che mi dicono gli elfi della notte. Parlare con fiori e alberi non fa per me, ma di sicuro Tannysa può aiutarti. Si trova nel ⟦Mage Quarter=Quartiere dei Maghi⟧, fuori da Alchemy Needs.", "." },
  ["a177cceed7a86248"] = { "Ci sono molti luoghi che potresti visitare a Teldrassil. Dimmi cosa cerchi.", "." },
  ["a1782b4d0c6a37a4"] = { "Continuerò a pattugliare la zona ancora per un po' per assicurarmi che sia davvero sicura.", "." },
  ["a1787ec11c883951"] = { "Non ne dubito. Forse un giorno potresti consegnare un messaggio a un mio vecchio amico. Ho sentito dire che vaga ancora per quei boschi.\n\n<Eitrigg china il capo per un momento, come in preghiera.>\n\nDunque Rend, sì... Rend e suo fratello Maim governavano la Guglia, in costante conflitto con i nani ⟦Dark Iron=Ferroscuro⟧. Riuscirono a scacciare i nani dalla parte alta della città, ma solo dopo l'arrivo dei draghi e solo dopo la morte di Maim.", "." },
  ["a17b4604700a6422"] = { "I miei occhi non mi ingannano mai, {race}. Vedo un grande potere in te: abbastanza potere, forse, da far avanzare la nostra causa. Raggiungimi in cima alla torre.", "." },
  ["a19009254ba94e94"] = { "%s sussurra freneticamente qualcosa a Shake's O'Breen.", "." },
  ["a1929c2e7630e1a3"] = { "Bah! Cassette della posta... ultimamente ricevo solo pubblicità!\n\nAumenta le dimensioni di questo... riduci le dimensioni di quello... agisci ora per ricevere gratis la tua Sword of Dragonslaying. Devo cambiare il numero della cassetta un mese sì e uno no!\n\nBeh, non dire che non ti avevo avvertito. Se cerchi la cassetta della posta, è proprio fuori dalla Stonefire Tavern.", "." },
  ["a19ed61a3ce4d74f"] = { "Allora vai da Bena's Alchemy, sul ripiano centrale, e parla con Bena in persona. Potrà aiutarti a padroneggiare l'arte della preparazione delle pozioni.", "." },
  ["a1a5cb0fa9d83c52"] = { "Certo! Facciamo un giro.", "." },
  ["a1aa82249b4b94ee"] = { "Stanotte il vostro sangue scorrerà rosso sulle pietre dei nostri altari.", "." },
  ["a1b0ce99d5589569"] = { "Continua, ti prego, Bodley.", "." },
  ["a1b21c6e4c725e30"] = { "Non lasciateli scappare!", "." },
  ["a1b3694d2eea9359"] = { "Be', che <saputello/saputella>! Ne sai più di me, te lo dico io! Non montarti la testa, ma se vuoi continuare a imparare, fai due chiacchiere con Georgio Bolero a ⟦Stormwind=Roccavento⟧. Dicono che in sartoria sappia il fatto suo!", "." },
  ["a1b8347a468c71db"] = { "Allora, vediamo se ho capito bene. Hai messo il frammento dello scettro che ⟦Anachronos=Anacronos⟧ aveva affidato al tuo Stormo dentro un pesciolino creato da te, e adesso ti aspetti che io costruisca una... una boa di arcanite o qualcosa del genere... per stanare il tuo pesciolino? E magari attirarmi l'ira di un Signore degli Elementi? Mi sfugge qualcosa? Magari devo farlo senza vestiti, durante un'eclissi di sole, in un anno bisestile?", "." },
  ["a1bb0a9ca31ec3b7"] = { "%s pianta i semi del frutto.", "." },
  ["a1bbaddf51e96718"] = { "Ah, salve. Hai l'aria di chi ha una domanda per me.", "." },
  ["a1bf13b43157a5aa"] = { "Le ⟦The Barrens=Savane⟧, con il loro sole cocente e gli abitanti ostili, sono il posto perfetto per mettere alla prova la tua forza e la tua tempra.", "." },
  ["a1c856836e5784eb"] = { "Grurk stupido? Tu prova aprire scatola! Forse tu furbo come gnomo???", "." },
  ["a1ef3baeb9b0e807"] = { "Piano! Ci stavo arrivando!\n\nDunque eccolo lì, ritto in piedi con tutto quel sangue e quelle budella che gli colavano addosso, quando chi ti arriva?\n\nI Ferroscuro! Non hai sentito una parola di quello che ho detto??\n\nBeh, i Ferroscuro sono un po' più furbi di quegli orchi ⟦Blackrock=Roccianera⟧. Sono arrivati preparati. E per preparati intendo che erano circa 300... *hic* scusa.", "." },
  ["a1fc4a83c10df844"] = { "Saluta il mio piccolo amico.", "." },
})
